window.MODELS = {
"block_tilt": "<!--\n  block_tilt.xml: a point finger tilts a 75 mm wooden cube about one of its bottom edges.\n\n  The block-tilting example of Hou and Mason, ICRA 2019, Sec. V, and ICRA 2021, Sec. VII. Units\n  are SI (m, kg, s, N). The cube (density 700 kg/m^3, mass 0.295 kg) rests on the table centred\n  at the origin; the plan rotates it about its bottom edge at x = +37.5 mm (the y axis through\n  (0.0375, 0, 0)), top toward +x. The finger is a 4 mm sphere of 0.1 kg on three slide joints\n  (x, y, z) driven by three force motors; ctrl is the finger force in newtons along the world\n  axes. The finger starts 0.5 mm above the top face at x = 30 mm, which is 0.1 L behind the\n  rotation edge, the hand position of the authors' block_tilting_control.m.\n\n  Friction 0.8 on every geom (the authors' estimate for table and hand), elliptic cones,\n  condim 3, impratio 10. solref \"0.002 1\" makes contacts stiffer than MuJoCo's default \"0.02 1\";\n  its time constant is 4 timesteps. impratio 10 makes sticking stiffer: under the HFVC of the\n  lab, the table edge creeps 0.05 mm over a 40 degree tilt, against 0.41 mm with impratio 1.\n  The finger cannot rotate, so a sticking contact moves over the 4 mm sphere and the contact\n  point on the top face shifts by r theta (2.8 mm at 40 degrees) without any sliding.\n\n  labs/hybrid_servoing/sim_block_tilt.py loads this file through mujoco.MjSpec and changes the\n  block size, the table height and the friction per trial; the geom names below are its handles.\n-->\n<mujoco model=\"block_tilt\">\n  <option timestep=\"0.0005\" gravity=\"0 0 -9.81\" cone=\"elliptic\" impratio=\"10\" integrator=\"implicitfast\"/>\n\n  <default>\n    <geom friction=\"0.8 0.005 0.0001\" condim=\"3\" solref=\"0.002 1\"/>\n    <joint type=\"slide\" armature=\"0\" damping=\"0\"/>\n  </default>\n\n  <worldbody>\n    <light pos=\"0 -0.3 0.5\" dir=\"0 0.5 -1\"/>\n    <geom name=\"table\" type=\"plane\" size=\"0.2 0.2 0.01\" rgba=\"0.85 0.85 0.85 1\"/>\n\n    <body name=\"block\" pos=\"0 0 0.0375\">\n      <freejoint name=\"block\"/>\n      <geom name=\"block\" type=\"box\" size=\"0.0375 0.0375 0.0375\" density=\"700\" rgba=\"0.76 0.60 0.42 1\"/>\n    </body>\n\n    <!-- Finger reference point; the slide joints measure its displacement from here. -->\n    <body name=\"finger\" pos=\"0.03 0 0.0795\">\n      <joint name=\"fx\" axis=\"1 0 0\" range=\"-0.1 0.1\"/>\n      <joint name=\"fy\" axis=\"0 1 0\" range=\"-0.1 0.1\"/>\n      <joint name=\"fz\" axis=\"0 0 1\" range=\"-0.1 0.1\"/>\n      <geom name=\"finger\" type=\"sphere\" size=\"0.004\" mass=\"0.1\" rgba=\"0.2 0.2 0.8 1\"/>\n    </body>\n  </worldbody>\n\n  <actuator>\n    <motor name=\"fx\" joint=\"fx\" ctrlrange=\"-200 200\" ctrllimited=\"true\"/>\n    <motor name=\"fy\" joint=\"fy\" ctrlrange=\"-200 200\" ctrllimited=\"true\"/>\n    <motor name=\"fz\" joint=\"fz\" ctrlrange=\"-200 200\" ctrllimited=\"true\"/>\n  </actuator>\n</mujoco>\n",
"box_on_plane": "<!--\n  box_on_plane.xml: a 0.1 m cube of 1 kg dropped from 0.25 m onto a plane.\n\n  Units are SI (m, kg, s, N). The cube's centre starts at z = 0.30 m, so its bottom face falls\n  0.25 m, lands at t = 0.226 s at 2.21 m/s, and comes to rest on four corner contacts whose\n  normal forces sum to m g = 9.81 N.\n\n  Loaded by the slides (lib/mj.js, MuJoCo 3.14.0 WebAssembly) and by the notebooks (Python\n  mujoco==3.14.0); tools/twins/mujoco.json checks that both engines step it to the same numbers.\n  Everything not set here is a MuJoCo default: Euler integrator, pyramidal friction cone,\n  impratio 1, solref \"0.02 1\", solimp \"0.9 0.95 0.001\", friction \"1 0.005 0.0001\".\n-->\n<mujoco model=\"box_on_plane\">\n  <option timestep=\"0.002\" gravity=\"0 0 -9.81\"/>\n\n  <worldbody>\n    <!-- Collision planes are infinite; size sets the drawn extent (1 m x 1 m, 0.05 m grid). -->\n    <geom name=\"floor\" type=\"plane\" size=\"0.5 0.5 0.05\" rgba=\"0.9 0.9 0.9 1\"/>\n\n    <body name=\"box\" pos=\"0 0 0.3\">\n      <freejoint name=\"box\"/>\n      <!-- Half-sizes 0.05 m give a 0.1 m cube; mass 1 kg sets the density to 1000 kg/m^3. -->\n      <geom name=\"box\" type=\"box\" size=\"0.05 0.05 0.05\" mass=\"1\" rgba=\"0.8 0.8 0.8 1\"/>\n    </body>\n  </worldbody>\n</mujoco>\n",
"tilted_plane": "<!--\n  tilted_plane.xml: a 1 kg block resting on a plane tilted by 20 degrees, friction mu = 0.5.\n\n  Units are SI (m, kg, s, N). The static friction angle is arctan(0.5) = 26.57 degrees, so at\n  20 degrees Coulomb friction holds the block and at 30 degrees it slides with acceleration\n  g (sin 30 - 0.5 cos 30) = 0.657 m/s^2. MuJoCo's soft contact lets the held block creep slowly\n  downhill; deck 19 measures that creep.\n\n  The ramp's priority=\"1\" makes its friction the contact's friction, whatever the block's value\n  (MuJoCo otherwise takes the larger of the two geoms' coefficients). A slide or notebook changes\n  mu by writing geom_friction[ramp, 0].\n\n  Changing the tilt at run time. The ramp is the plane rotated by theta about +y, so its local\n  x axis points downhill along (cos theta, 0, -sin theta). To set a new tilt theta:\n    geom_quat[ramp]   = (cos(theta/2), 0, sin(theta/2), 0)\n    block qpos[0:3]   = (h sin theta, 0, h cos theta)          h = 0.025 m, the block's half-height\n    block qpos[3:7]   = (cos(theta/2), 0, sin(theta/2), 0)\n    qvel = 0, then mj_forward.\n  In lib/mj.js: sim.reset(); sim.geomParam(\"ramp\", {quat}); write qpos; sim.forward().\n  The XML below is that state for theta = 20 degrees (h sin 20 = 0.0085505, h cos 20 = 0.0234923).\n  Keep the XML tilt nonzero: a geom whose pose equals its body's frame is compiled with\n  geom_sameframe = 1, and MuJoCo then ignores later writes to its geom_quat until\n  geom_sameframe is set to 0 (sim.geomParam does that).\n-->\n<mujoco model=\"tilted_plane\">\n  <option timestep=\"0.002\" gravity=\"0 0 -9.81\"/>\n\n  <worldbody>\n    <!-- 2 m long (local x), 0.6 m wide; drawn with a 0.05 m grid. -->\n    <geom name=\"ramp\" type=\"plane\" size=\"1 0.3 0.05\" euler=\"0 20 0\" priority=\"1\"\n          friction=\"0.5 0.005 0.0001\" rgba=\"0.9 0.9 0.9 1\"/>\n\n    <body name=\"block\" pos=\"0.0085505 0 0.0234923\" euler=\"0 20 0\">\n      <freejoint name=\"block\"/>\n      <!-- 0.1 m x 0.1 m footprint, 0.05 m tall, 1 kg. -->\n      <geom name=\"block\" type=\"box\" size=\"0.05 0.05 0.025\" mass=\"1\" rgba=\"0.8 0.8 0.8 1\"/>\n    </body>\n  </worldbody>\n</mujoco>\n",
"two_finger_pinch": "<!--\n  two_finger_pinch.xml: two slide-jointed fingers squeeze a 0.2 kg box from the sides.\n\n  Units are SI (m, kg, s, N). Each finger is a pad on a horizontal slide joint (axis x) driven by\n  a force motor; ctrl is the squeeze force in newtons, pushing each pad toward the box. Gravity\n  pulls the box down; only friction at the two pads holds it. With pad friction mu and squeeze\n  force F on each side, Coulomb friction holds the box when 2 mu F >= m g, that is\n  F >= 0.2 * 9.81 / (2 mu) = 1.96 N for mu = 0.5. Below that the box slips and falls 0.07 m to\n  the floor. MuJoCo's soft friction lets a held box creep: with 5 N per pad (the \"hold\" key)\n  it slides down at 4.8 mm/s with the default pyramidal cone and 2.6 mm/s with the elliptic\n  cone (Python mujoco 3.14.0, 0.5 s to 3 s); with 1.5 N it reaches the floor within 1 s.\n\n  The pads have priority=\"1\", so their friction sets the pad-box contacts' friction; a slide or\n  notebook changes mu by writing geom_friction[left, 0] and geom_friction[right, 0].\n  The keyframe \"hold\" squeezes with 5 N on each side.\n-->\n<mujoco model=\"two_finger_pinch\">\n  <option timestep=\"0.002\" gravity=\"0 0 -9.81\"/>\n\n  <default>\n    <!-- Joint damping settles the pads onto the box without ringing. -->\n    <joint type=\"slide\" axis=\"1 0 0\" damping=\"2\" range=\"-0.05 0.05\" limited=\"true\"/>\n    <geom rgba=\"0.8 0.8 0.8 1\"/>\n  </default>\n\n  <worldbody>\n    <geom name=\"floor\" type=\"plane\" size=\"0.25 0.25 0.05\" rgba=\"0.9 0.9 0.9 1\"/>\n\n    <!-- Pads: 0.02 m thick (x), 0.04 m wide (y), 0.04 m tall (z), touching the box faces at x = -+0.03. -->\n    <body name=\"left\" pos=\"-0.04 0 0.1\">\n      <joint name=\"left\"/>\n      <geom name=\"left\" type=\"box\" size=\"0.01 0.02 0.02\" mass=\"0.1\" priority=\"1\" friction=\"0.5 0.005 0.0001\"/>\n    </body>\n    <body name=\"right\" pos=\"0.04 0 0.1\">\n      <joint name=\"right\"/>\n      <geom name=\"right\" type=\"box\" size=\"0.01 0.02 0.02\" mass=\"0.1\" priority=\"1\" friction=\"0.5 0.005 0.0001\"/>\n    </body>\n\n    <!-- The held object: a 0.06 m cube of 0.2 kg, centred between the pads 0.1 m above the floor. -->\n    <body name=\"box\" pos=\"0 0 0.1\">\n      <freejoint name=\"box\"/>\n      <geom name=\"box\" type=\"box\" size=\"0.03 0.03 0.03\" mass=\"0.2\"/>\n    </body>\n  </worldbody>\n\n  <actuator>\n    <!-- Positive ctrl pushes each pad toward the box: +x for the left pad, -x for the right pad. -->\n    <motor name=\"left\" joint=\"left\" gear=\"1\" ctrlrange=\"0 20\" ctrllimited=\"true\"/>\n    <motor name=\"right\" joint=\"right\" gear=\"-1\" ctrlrange=\"0 20\" ctrllimited=\"true\"/>\n  </actuator>\n\n  <keyframe>\n    <key name=\"hold\" ctrl=\"5 5\"/>\n  </keyframe>\n</mujoco>\n"
};
